    "A_guarantee": "主合同无效，丁的从属保证合同亦无效；本次依据保证合同要求丁立即给付的请求不支持，金额为0.00元。",
    "B_initial_principal": "187030.00",
    "B_protected_total": "203220.81",
    "B_guarantee": "戊的连带责任保证有效，甲已在保证期间内依法行权；戊对B剩余全部受保护债务承担连带保证责任，不因内部50%分担约定而减半。",
    "C_outstanding_principal": "152860.88",
    "C_outstanding_interest": "1415.53",
    "C_outstanding_expenses": "0.00",
    "C_guarantee": "己原为一般保证人，保证责任在SP-01付款时尚存续，但享有先诉抗辩；S14随后将C全部剩余债务转移给辛，未经己书面同意，己对该全部转移债务不再承担保证责任。本次立即给付金额为0.00元。",
    "borrower_total": "326036.81",
    "B_second_guarantee": "庚的连带责任保证有效；2023-07-06完整给付请求已在保证期间内到达庚，故保证责任未消灭。本次可请求庚就B剩余203220.81元承担连带保证责任。",
    "B_joint_payment_limit": "203220.81",
    "C_third_party_type": "免责的债务承担，即C全部剩余债务转移给辛、乙退出；不是债务加入，也不是保证。",
    "C_third_party_payment_limit": "154276.41",
    "C_original_borrower_liability": "0.00",
    "basis": {
      "适用范围与精度": "仅依据明示虚构材料及随题规范摘录评价截至2023-08-01的请求，不计当日利息。以下中间小数仅作展示，计算连续使用未取整数值；最终各金额四舍五入到分后再合计。",
      "A": {
        "事实与规范": "S01确认A于2022年成立且资金来自套取银行信贷，应依lending-2020-12第13条认定无效；乙不知资金来源、利率仅6%不排除该项无效事由，不能套用lending-2015第14条的旧条件。依civil-code-2020第157、682条及S02、S12，乙返还尚未返还的实际财产，丁不承担有效保证合同项下责任；本题未请求保证无效后的过错赔偿。",
        "计算": "143123.00－20307.00＝122816.00元。未交付票面差额不计，同一到账交易号的收据不构成第二次交付。"
      },
      "B金额": {
        "本金与利率": "S03—S05载明预扣利息12551.00元、实际到账187030.00元，归档均无新增交付。依civil-code-2020第670、679条及lending-2020-12第25—27条，最初本金为187030.00元，约定年利率13.2%低于3.70%×4＝14.8%。纸面归档数额不能使不受保护的金额成为本金。",
        "连续结息": [
          {
            "期间": "2022-01-12至2022-07-06",
            "天数": 175,
            "计算": "P1＝187030×(1＋0.132×175/365)",
            "合法结息后本金_展示值": "198866.69315068"
          },
          {
            "期间": "2022-07-06至2022-10-17",
            "天数": 103,
            "计算": "P2＝P1×(1＋0.132×103/365)",
            "合法结息后本金_展示值": "206274.34126048"
          },
          {
            "期间": "2022-10-17至2023-01-09",
            "天数": 84,
            "计算": "P3＝P2×(1＋0.132×84/365)",
            "合法结息后本金_展示值": "212540.56015335"
          },
          {
            "期间": "2023-01-09至2023-08-01",
            "天数": 204,
            "计算": "候选本息＝P3×(1＋0.132×204/365)",
            "候选本息_展示值": "228220.81276653"
          }
        ],
        "独立上限与付款": "全期175＋103＋84＋204＝566天。lending-2020-12第27条的整体上限＝187030×(1＋0.148×566/365)＝229953.64120548元，高于合法结息候选本息，故付款前取228220.81276653元。逾期段依第28条按借期内利率处理。SP-01抵充B后，未偿余额为228220.81276653－25000＝203220.81276653元，最终取203220.81元。"
      },
      "B保证": "依S06、civil-code-2020第688、692、693、695条及guarantee-2020第25、31、32条，戊的无条件清偿条款构成连带保证，庚亦明确承担全额连带保证。‘直至还清’属于保证期间约定不明；未经二人书面同意的展期不改变保证期间，均按原到期日2023-01-12起算六个月，至2023-07-12届满。对戊的诉状于2023-07-07实际送达，随后撤诉不否定期间内行权；对庚的完整请求于2023-07-06直接到达，同样及时。依guarantee-2020第13、29条，内部各50%是追偿分担约定，不是对甲的责任上限；本题不存在未向庚及时行权导致戊丧失追偿权的事实，戊减责、庚免责主张均不成立。戊、庚各自立即给付上限均为203220.81元，属于同一B债务的责任覆盖，不重复累加。",
      "C金额": {
        "利率与抵充规则": "依S07—S09、lending-2015第26条及lending-2020-12第25、28、31条，2019-02-07至2020-08-19按23.5%计算，自2020-08-20起按题设起诉时一年期LPR的四倍即13%计算。原合同明确费用、合法利息、本金的顺序，T-02另有双方签署的本金优先补充协议；其他付款的单方备注不能变更原约定。2021年前付款直接依据原合同及补充协议处理，不追溯援引民法典第561条；此后处理亦与该条一致。未付利息不另计息。",
        "计算方法": "逐段新增利息＝该段未偿本金×适用年利率×实际天数/365；按约定分配付款，付款日不再对已偿本金计息。",
        "付款后余额核对": [
          {
            "交易": "T-01",
            "日期": "2019-04-18",
            "本段天数": 70,
            "处理": "25247元先偿费用1680元、利息10266.15205479元，余款偿本金。",
            "剩余本金_展示值": "214489.15205479",
            "剩余利息_展示值": "0.00000000"
          },
          {
            "交易": "T-02",
            "日期": "2019-08-23",
            "本段天数": 127,
            "处理": "依双方补充协议，26978元全部偿本金，本段利息保留。",
            "剩余本金_展示值": "187511.15205479",
            "剩余利息_展示值": "17538.16093993"
          },
          {
